import { DurableObject } from 'cloudflare:workers';
import { Lifecycle } from 'agents/lifecycle';
import { MCPClientManager } from 'agents/mcp/client';

const SERVER_ID = 'tools';

// A plain Durable Object (not an Agent). Our other Workers call listTools() over RPC.
export class ToolGateway extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    // The manager persists registered servers in this object's SQLite storage
    // and restores them from its onStart when the lifecycle starts after eviction.
    this.mcp = new MCPClientManager('tool-gateway', '1.0.0', { env });
    this.lifecycle = Lifecycle.install(this).use(this.mcp);
  }

  async listTools() {
    // Native RPC bypasses fetch, so start the lifecycle (and restore connections) explicitly.
    await this.lifecycle.start();
    await this.#ensureServer();
    await this.mcp.waitForConnections({ timeout: 30_000 });
    return this.mcp.listTools({ serverId: SERVER_ID });
  }

  async #ensureServer() {
    const url = this.env.TOOLS_MCP_URL;
    const stored = this.mcp.listServers().find((s) => s.id === SERVER_ID);
    if (stored?.server_url === url) return;
    if (stored) await this.mcp.removeServer(SERVER_ID);

    await this.mcp.registerServer(SERVER_ID, { url, name: 'tools' });
    const result = await this.mcp.connectToServer(SERVER_ID);
    if (result.state === 'failed') throw new Error(`MCP connect failed: ${result.error}`);
    if (result.state === 'authenticating') throw new Error('MCP server requires OAuth, which ToolGateway does not support');
    await this.mcp.discoverIfConnected(SERVER_ID);
  }
}
